def transform(grid):
    """Return the panel before the monochrome separator, recolored as a mask."""
    h, w = len(grid), len(grid[0])
    # Divider is a full row or column of a single color.
    row_div = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if row_div is not None:
        panel = [row[:] for row in grid[:row_div]]
    else:
        col_div = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        panel = [row[:col_div] for row in grid]
    colors = {}
    for row in panel:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    bg = max(colors, key=colors.get)
    fg = next((v for v in colors if v != bg), bg)
    return [[3 if v == fg else 7 for v in row] for row in panel]
